    #[test]
    fn concurrent_collectors_merge_one_minute_without_duplicate_rows() {
        let path = database_path("concurrent-merge");
        drop(UsageStore::open(&path).unwrap());
        let barrier = Arc::new(Barrier::new(2));
        let first = sample(1_700_000_060, 1_700_604_800, Some(75.0), 1.25);
        let mut second = first.clone();
        second.sol_dollars = 4.5;
        second.sol_tokens = 900;
        let expected_second = second.clone();
        let left_path = path.clone();
        let left_barrier = Arc::clone(&barrier);
        let left = std::thread::spawn(move || {
            let store = UsageStore::open(left_path).unwrap();
            left_barrier.wait();
            store.upsert_sample(&first).unwrap();
        });
        let right_path = path.clone();
        let right_barrier = Arc::clone(&barrier);
        let right = std::thread::spawn(move || {
            let store = UsageStore::open(right_path).unwrap();
            right_barrier.wait();
            store.upsert_sample(&second).unwrap();
        });
        left.join().unwrap();
        right.join().unwrap();
        let rows = UsageStore::open(&path).unwrap().load_all().unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0], expected_second);
        remove_database(&path);
    }

    fn with_backup_rename_failures<T>(failures: &[usize], run: impl FnOnce() -> T) -> T {
        struct Reset;
        impl Drop for Reset {
            fn drop(&mut self) {
                BACKUP_RENAME_FAULTS.with(|faults| *faults.borrow_mut() = (0, Vec::new()));
            }
        }
        BACKUP_RENAME_FAULTS.with(|faults| *faults.borrow_mut() = (0, failures.to_vec()));
        let _reset = Reset;
        run()
    }

    fn distinct_backup_rotation_fixture(label: &str) -> (PathBuf, Vec<Vec<u8>>, Vec<u8>) {
        let path = database_path(label);
        let store = UsageStore::open(&path).unwrap();
        for dollars in [1.0, 2.0, 3.0] {
            store
                .upsert_sample(&sample(1_700_000_060, 1_700_604_800, Some(75.0), dollars))
                .unwrap();
            UsageStore::backup_generations(&path, 3).unwrap();
        }
        store
            .upsert_sample(&sample(1_700_000_060, 1_700_604_800, Some(75.0), 4.0))
            .unwrap();
        drop(store);
        let old_generations = (1..=3)
            .map(|generation| {
                fs::read(path.with_extension(format!("sqlite3.bak.{generation}"))).unwrap()
            })
            .collect::<Vec<_>>();
        assert!(
            old_generations[0] != old_generations[1] && old_generations[1] != old_generations[2]
        );
        let source = fs::read(&path).unwrap();
        (path, old_generations, source)
    }

    #[test]
    fn backup_rotation_rename_failures_restore_each_original_generation() {
        let mut mismatches = Vec::new();
        // Three staging moves, publishing the new backup, then two retained
        // generation moves. Each failure observes the public operation.
        for failed_rename in 1..=6 {
            let (path, old, source) = distinct_backup_rotation_fixture("rotation-rename-fault");
            let result = with_backup_rename_failures(&[failed_rename], || {
                UsageStore::backup_generations(&path, 3)
            });
            assert!(result
                .unwrap_err()
                .to_string()
                .contains("injected backup rename failure"));
            assert_eq!(
                fs::read(&path).unwrap(),
                source,
                "source changed at rename {failed_rename}"
            );
            for (index, expected) in old.iter().enumerate() {
                let generation = index + 1;
                let actual =
                    fs::read(path.with_extension(format!("sqlite3.bak.{generation}"))).ok();
                if actual.as_ref() != Some(expected) {
                    mismatches.push((failed_rename, generation));
                }
            }
            remove_database(&path);
        }
        assert!(
            mismatches.is_empty(),
            "lost or replaced original backup at (failed rename, generation): {mismatches:?}"
        );
    }

    #[test]
    fn backup_rotation_failed_undo_preserves_recoverable_old_bytes() {
        let mut lost = Vec::new();
        // Undo failure during initial staging, new-backup publication, and
        // retained-generation publication must never consume old copies.
        for faults in [[2, 3], [5, 6], [6, 7]] {
            let (path, old, source) = distinct_backup_rotation_fixture("rotation-undo-fault");
            let result =
                with_backup_rename_failures(&faults, || UsageStore::backup_generations(&path, 3));
            assert!(result
                .unwrap_err()
                .to_string()
                .contains("injected backup rename failure"));
            assert_eq!(
                fs::read(&path).unwrap(),
                source,
                "source changed for {faults:?}"
            );
            let retained = fs::read_dir(path.parent().unwrap())
                .unwrap()
                .filter_map(|entry| {
                    let path = entry.ok()?.path();
                    path.is_file().then(|| fs::read(path).ok()).flatten()
                })
                .collect::<Vec<_>>();
            for (index, expected) in old.iter().enumerate() {
                if !retained.contains(expected) {
                    lost.push((faults, index + 1));
                }
            }
            remove_database(&path);
        }
        assert!(
            lost.is_empty(),
            "old generation bytes lost after failed undo: {lost:?}"
        );
    }

    #[test]
    fn backup_generations_are_sqlite_consistent_and_bounded() {
        let path = database_path("backup-generations");
        let first = sample(1_700_000_060, 1_700_604_800, Some(75.0), 1.25);
        let store = UsageStore::open(&path).unwrap();
        store.upsert_sample(&first).unwrap();
        drop(store);
        for _ in 0..4 {
            UsageStore::backup_generations(&path, 3).unwrap();
        }
        for generation in 1..=3 {
            let backup = path.with_extension(format!("sqlite3.bak.{generation}"));
            assert!(backup.is_file(), "missing backup generation {generation}");
            let connection = Connection::open(&backup).unwrap();
            let quick_check: String = connection
                .query_row("PRAGMA quick_check", [], |row| row.get(0))
                .unwrap();
            assert_eq!(quick_check, "ok");
            assert_eq!(
                UsageStore::open(&backup).unwrap().load_all().unwrap(),
                vec![first.clone()]
            );
        }
        assert!(!path.with_extension("sqlite3.bak.4").exists());
        remove_database(&path);
    }

    #[test]
    fn failed_backup_rotation_keeps_existing_generation_untouched() {
        let path = database_path("backup-rotation-failure");
        let original = sample(1_700_000_060, 1_700_604_800, Some(75.0), 1.25);
        let store = UsageStore::open(&path).unwrap();
        store.upsert_sample(&original).unwrap();
        drop(store);
        UsageStore::backup_generations(&path, 3).unwrap();
        let first = path.with_extension("sqlite3.bak.1");
        let before = fs::read(&first).unwrap();

        // A non-regular generation is rejected before rotation starts. The
        // current DB and the already usable generation must remain intact.
        let blocked = path.with_extension("sqlite3.bak.2");
        fs::create_dir(&blocked).unwrap();
        assert!(UsageStore::backup_generations(&path, 3).is_err());
        assert_eq!(fs::read(&first).unwrap(), before);
        assert_eq!(
            UsageStore::open(&path).unwrap().load_all().unwrap(),
            vec![original]
        );
        fs::remove_dir(&blocked).unwrap();
        remove_database(&path);
    }

    #[test]
    fn backup_and_migration_never_repair_the_protected_source() {
        let path = database_path("backup-migration-read-only-source");
        let original = sample(1_700_000_060, 1_700_604_800, Some(75.0), 1.25);
        let store = UsageStore::open(&path).unwrap();
        store.upsert_sample(&original).unwrap();
        drop(store);

        let connection = Connection::open(&path).unwrap();
        connection
            .execute("DROP INDEX usage_history_timestamp_reset_idx", [])
            .unwrap();
        drop(connection);
        #[cfg(unix)]
        fs::set_permissions(&path, fs::Permissions::from_mode(0o640)).unwrap();
        let source_before = fs::read(&path).unwrap();

        let blocked = path.with_extension("sqlite3.bak.2");
        fs::create_dir(&blocked).unwrap();
        assert!(UsageStore::backup_generations(&path, 3).is_err());
        assert_eq!(fs::read(&path).unwrap(), source_before);
        #[cfg(unix)]
        assert_eq!(
            fs::metadata(&path).unwrap().permissions().mode() & 0o777,
            0o640
        );
        fs::remove_dir(&blocked).unwrap();

        let report = UsageStore::migrate_verified(&path, |samples| Ok(samples.to_vec())).unwrap();
        assert_eq!(fs::read(&report.preserved_backup).unwrap(), source_before);
        let migrated =
            Connection::open_with_flags(&path, OpenFlags::SQLITE_OPEN_READ_ONLY).unwrap();
        let index_present: bool = migrated
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM pragma_index_list('usage_history') WHERE name = ?1)",
                [HISTORY_TIMESTAMP_RESET_INDEX],
                |row| row.get(0),
            )
            .unwrap();
        assert!(
            index_present,
            "only the validated candidate may repair schema"
        );
        drop(migrated);
        remove_database(&path);
    }

