    #[test]
    fn observation_json_round_trip_preserves_binary64_storage_value() {
        let mut expected = sample(1_700_000_040, 1_700_604_800, Some(71.0), 1.0);
        // This exact value exposed the production startup failure: without
        // serde_json's round-trip parser the JSON path moved by one ULP from
        // the same value stored as SQLite REAL.
        expected.luna_dollars = f64::from_bits(0x3ffcd65251dc6ba7);
        let observation = UsageHistoryObservation::confirmed(&expected);
        let decoded = observation_from_sql(
            observation.timestamp,
            observation_data_hash(observation.reset_at, observation.timestamp),
            observation_json(&observation).unwrap(),
        )
        .unwrap();

        assert_eq!(
            decoded.luna_dollars.map(f64::to_bits),
            Some(expected.luna_dollars.to_bits())
        );
        assert!(observation_matches_sample(&decoded, &expected));
    }

    #[test]
    fn durable_observation_writes_preserve_sqlite_binary64() {
        let path = database_path("durable-sqlite-binary64");
        let identity = partition_identity('a', 1);
        let mut store = UsageStore::create_partitioned(&path, &identity).unwrap();
        for (index, bits) in [
            0x40193633cbb473e5_u64,
            0x3ffcd65251dc6ba7,
            1.5_f64.to_bits(),
        ]
        .into_iter()
        .enumerate()
        {
            let at = 1_800_000_000 + index as i64 * 60;
            let amount = f64::from_bits(bits);
            let mut expected = sample(at, 1_800_604_800, Some(amount), amount);
            expected.sol_dollars = amount;
            expected.terra_dollars = amount;
            expected.luna_dollars = amount;
            let observation = UsageHistoryObservation::confirmed(&expected);
            store
                .commit_session_collection_with_observations(
                    SessionCollectionCommit {
                        reset_at: expected.reset_at,
                        window_seconds: 604800,
                        collector_epoch: 1,
                        cycle_seq: index as u64 + 1,
                        samples: std::slice::from_ref(&expected),
                        checkpoints: &[],
                        ranges: &[],
                        model_totals: &[],
                        recorded_sessions: &[],
                    },
                    std::slice::from_ref(&observation),
                )
                .expect("identical canonical and JSON values must pass the strict storage guard");
            let json:String=store.connection.query_row("SELECT snapshot_json FROM durable_state WHERE singleton>=2 AND data_generation=?1",[at],|r|r.get(0)).unwrap();
            for field in [
                "remaining_percent",
                "sol_dollars",
                "terra_dollars",
                "luna_dollars",
            ] {
                let actual: f64 = store
                    .connection
                    .query_row(
                        "SELECT json_extract(?1,?2)",
                        params![&json, format!("$.{field}")],
                        |r| r.get(0),
                    )
                    .unwrap();
                assert_eq!(actual.to_bits(), bits, "SQLite field={field}");
                let decoded: serde_json::Value = serde_json::from_str(&json).unwrap();
                assert_eq!(
                    decoded[field].as_f64().unwrap().to_bits(),
                    bits,
                    "Serde field={field}"
                );
            }
            let saved = store
                .load_all_raw()
                .unwrap()
                .into_iter()
                .find(|r| r.timestamp == at)
                .unwrap();
            assert_eq!(saved.remaining_percent.unwrap().to_bits(), bits);
            assert_eq!(saved.sol_dollars.to_bits(), bits);
            assert_eq!(saved.terra_dollars.to_bits(), bits);
            assert_eq!(saved.luna_dollars.to_bits(), bits);
        }
        drop(store);
        remove_database(&path);
    }

    #[test]
    fn weekly_empty_model_set_survives_commit_reopen_and_replay() {
        let path = database_path("weekly-empty-model-set-replay");
        let first_timestamp = 1_700_000_040;
        let reset_at = first_timestamp + 604_800;
        let mut samples = (0..4)
            .map(|index| sample(first_timestamp + index * 60, reset_at, Some(95.0), 0.0))
            .collect::<Vec<_>>();
        for sample in &mut samples[..3] {
            sample.sol_dollars = 0.0;
            sample.terra_dollars = 0.0;
            sample.luna_dollars = 0.0;
            sample.sol_tokens = 0;
            sample.terra_tokens = 0;
            sample.luna_tokens = 0;
        }
        samples[3].sol_dollars = 1.0;
        samples[3].terra_dollars = 0.0;
        samples[3].luna_dollars = 0.0;
        samples[3].sol_tokens = 5;
        samples[3].terra_tokens = 0;
        samples[3].luna_tokens = 0;

        let model = SessionModelTotal {
            model: "SOL".into(),
            total_tokens: 5,
            input_tokens: Some(4),
            cached_input_tokens: Some(1),
            output_tokens: Some(1),
            cache_write_input_tokens: Some(0),
        };
        let mut observations = samples
            .iter()
            .map(UsageHistoryObservation::confirmed)
            .collect::<Vec<_>>();
        observations[1].model_totals = Some(Vec::new());
        observations[1].model_totals_complete = true;
        observations[2].model_totals = Some(Vec::new());
        observations[3].model_totals = Some(vec![model.clone()]);
        observations[3].model_totals_complete = true;
        let commit = || SessionCollectionCommit {
            reset_at,
            window_seconds: 604_800,
            collector_epoch: 550,
            cycle_seq: 1,
            samples: &samples,
            checkpoints: &[],
            ranges: &[],
            model_totals: std::slice::from_ref(&model),
            recorded_sessions: &[],
        };
        let expected = observations.clone();
        let now = Utc.timestamp_opt(first_timestamp + 600, 0).unwrap();

        {
            let mut store =
                UsageStore::create_partitioned(&path, &partition_identity('a', 1)).unwrap();
            let committed = store
                .commit_session_collection_with_observations(commit(), &observations)
                .unwrap();
            assert_eq!(committed.data_generation, 1);
            assert_eq!(committed.canonical_observations, expected);

            let missing_model_json: String = store
                .connection
                .query_row(
                    "SELECT snapshot_json FROM durable_state WHERE data_hash = ?1",
                    [observation_data_hash(
                        observations[0].reset_at,
                        observations[0].timestamp,
                    )],
                    |row| row.get(0),
                )
                .unwrap();
            let old_contract = validate_observation_json(&missing_model_json).unwrap();
            assert!(old_contract.get("empty_model_set_complete").is_none());
            assert_eq!(
                observation_from_sql(
                    observations[0].timestamp,
                    observation_data_hash(observations[0].reset_at, observations[0].timestamp),
                    missing_model_json,
                )
                .unwrap()
                .model_totals,
                None,
                "legacy JSON without empty-set metadata remains unspecified"
            );

            let complete_empty_json: String = store
                .connection
                .query_row(
                    "SELECT snapshot_json FROM durable_state WHERE data_hash = ?1",
                    [observation_data_hash(
                        observations[1].reset_at,
                        observations[1].timestamp,
                    )],
                    |row| row.get(0),
                )
                .unwrap();
            let complete_empty_json: serde_json::Value =
                serde_json::from_str(&complete_empty_json).unwrap();
            assert_eq!(
                complete_empty_json
                    .get("empty_model_set_complete")
                    .and_then(serde_json::Value::as_bool),
                Some(true)
            );

            let incomplete_empty_json: String = store
                .connection
                .query_row(
                    "SELECT snapshot_json FROM durable_state WHERE data_hash = ?1",
                    [observation_data_hash(
                        observations[2].reset_at,
                        observations[2].timestamp,
                    )],
                    |row| row.get(0),
                )
                .unwrap();
            let incomplete_empty_json: serde_json::Value =
                serde_json::from_str(&incomplete_empty_json).unwrap();
            assert_eq!(
                incomplete_empty_json
                    .get("empty_model_set_complete")
                    .and_then(serde_json::Value::as_bool),
                Some(false)
            );

            let mut wrong_type = complete_empty_json.clone();
            wrong_type.as_object_mut().unwrap().insert(
                "empty_model_set_complete".into(),
                serde_json::Value::String("true".into()),
            );
            assert!(validate_observation_json(&wrong_type.to_string()).is_err());

            let mut contradictory = complete_empty_json.clone();
            contradictory
                .as_object_mut()
                .unwrap()
                .insert("sol_tokens".into(), serde_json::Value::from(1));
            assert!(validate_observation_json(&contradictory.to_string()).is_err());

            let unavailable =
                UsageHistoryObservation::unavailable(first_timestamp + 240, reset_at, Some(95.0));
            let mut unavailable_json: serde_json::Value =
                serde_json::from_str(&observation_json(&unavailable).unwrap()).unwrap();
            unavailable_json.as_object_mut().unwrap().insert(
                "empty_model_set_complete".into(),
                serde_json::Value::Bool(false),
            );
            assert!(validate_observation_json(&unavailable_json.to_string()).is_err());
        }

        let mut store = UsageStore::open(&path).unwrap();
        assert_eq!(
            store.load_recent_observations(now).unwrap(),
            expected,
            "the committed durable observation must distinguish absent and complete/incomplete empty model sets"
        );
        let replay = store
            .commit_session_collection_with_observations(commit(), &observations)
            .unwrap();
        assert_eq!(replay.data_generation, 1, "replay keeps its generation");
        assert_eq!(replay.canonical_observations, expected);
        assert_eq!(store.load_recent_observations(now).unwrap(), expected);
        drop(store);

        let reopened = UsageStore::open(&path).unwrap();
        assert_eq!(reopened.load_recent_observations(now).unwrap(), expected);
        drop(reopened);

        let mut conflicted_store = UsageStore::open(&path).unwrap();
        conflicted_store
            .connection
            .execute(
                "INSERT INTO usage_model_history (
                    reset_at, timestamp, model, total_tokens, input_tokens,
                    cached_input_tokens, output_tokens, cache_write_input_tokens,
                    model_set_complete
                 ) VALUES (?1, ?2, 'SOL', '1', '1', '0', '0', NULL, 1)",
                params![reset_at, observations[1].timestamp],
            )
            .unwrap();
        assert!(matches!(
            conflicted_store.load_recent_observations_raw(now),
            Err(UsageStoreError::InvalidImport(_))
        ));
        let transaction = conflicted_store
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .unwrap();
        assert!(upsert_observation_model_totals(
            &transaction,
            std::slice::from_ref(&observations[1]),
            true,
            None,
        )
        .is_err());
        drop(transaction);
        drop(conflicted_store);
        remove_database(&path);
    }

    #[test]
    fn observation_source_transitions_are_monotonic_and_same_minute_updates_commit() {
        let path = database_path("observation-source-transitions");
        let timestamp = 1_700_000_040;
        let reset_at = 1_700_604_800;
        let mut store = UsageStore::open(&path).unwrap();

        let unavailable = UsageHistoryObservation::unavailable(timestamp, reset_at, Some(90.0));
        let transaction = store
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .unwrap();
        assert_eq!(
            upsert_observations(&transaction, std::slice::from_ref(&unavailable)).unwrap(),
            vec![unavailable.clone()]
        );
        transaction.commit().unwrap();

        // A later quota-only reading for the same minute must update the
        // unavailable sidecar instead of producing a permanent batch conflict.
        let later_unavailable =
            UsageHistoryObservation::unavailable(timestamp, reset_at, Some(80.0));
        let transaction = store
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .unwrap();
        assert_eq!(
            upsert_observations(&transaction, std::slice::from_ref(&later_unavailable),).unwrap(),
            vec![later_unavailable.clone()]
        );
        transaction.commit().unwrap();

        let confirmed_sample = sample(timestamp, reset_at, Some(82.0), 4.0);
        let confirmed = UsageHistoryObservation::confirmed(&confirmed_sample);
        let transaction = store
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .unwrap();
        assert_eq!(
            upsert_observations(&transaction, std::slice::from_ref(&confirmed)).unwrap(),
            vec![confirmed.clone()]
        );
        transaction.commit().unwrap();

        // An unavailable retry cannot downgrade an already confirmed vector.
        let attempted_downgrade =
            UsageHistoryObservation::unavailable(timestamp, reset_at, Some(70.0));
        let transaction = store
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate)
            .unwrap();
        assert_eq!(
            upsert_observations(&transaction, std::slice::from_ref(&attempted_downgrade),).unwrap(),
            vec![confirmed.clone()]
        );
        transaction.commit().unwrap();

        let observations = store
            .load_recent_observations(Utc.timestamp_opt(timestamp + 60, 0).unwrap())
            .unwrap();
        assert_eq!(observations.len(), 1);
        assert_eq!(observations[0], confirmed);
        drop(store);
        remove_database(&path);
    }

    #[test]
    fn old_durable_state_check_migrates_before_validation_and_preserves_row_one() {
        let path = database_path("durable-state-check-migration");
        let expected = sample(1_700_000_060, 1_700_604_800, Some(75.0), 1.25);
        let durable = {
            let mut store = UsageStore::open(&path).unwrap();
            store.upsert_sample(&expected).unwrap();
            store
                .commit_durable_state(&[], "0".repeat(64), r#"{"kind":"legacy-row-one"}"#)
                .unwrap()
        };

        let connection = Connection::open(&path).unwrap();
        connection
            .execute_batch(
                "ALTER TABLE durable_state RENAME TO durable_state_legacy;
                 CREATE TABLE durable_state (
                     singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
                     data_generation INTEGER NOT NULL CHECK (data_generation >= 0),
                     data_hash TEXT NOT NULL,
                     snapshot_json TEXT NOT NULL
                 );
                 INSERT INTO durable_state
                     (singleton, data_generation, data_hash, snapshot_json)
                 SELECT singleton, data_generation, data_hash, snapshot_json
                 FROM durable_state_legacy;
                 DROP TABLE durable_state_legacy;",
            )
            .unwrap();
        drop(connection);

        let reopened = UsageStore::open(&path).unwrap();
        assert_eq!(reopened.load_all().unwrap(), vec![expected]);
        assert_eq!(reopened.load_durable_record().unwrap(), Some(durable));
        drop(reopened);

        let connection = Connection::open(&path).unwrap();
        let durable_sql: String = connection
            .query_row(
                "SELECT sql FROM sqlite_schema
                 WHERE type = 'table' AND name = 'durable_state'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let normalized = durable_sql
            .to_ascii_lowercase()
            .chars()
            .filter(|character| !character.is_whitespace())
            .collect::<String>();
        assert!(normalized.contains("singleton>=1"));
        let singleton_count: i64 = connection
            .query_row("SELECT COUNT(*) FROM durable_state", [], |row| row.get(0))
            .unwrap();
        assert_eq!(singleton_count, 1);
        drop(connection);
        remove_database(&path);
    }

